def init():
    return dict(phase=0, tx=1, count=0, data=0, bit_index=0)

def step(state, inputs):
    div = int(inputs.get("DIV", 868))
    if div < 1:
        div = 1

    if inputs.get("rst", 0):
        state = init()
    else:
        phase = state.get("phase", 0)
        tx = state.get("tx", 1)
        count = state.get("count", 0)
        data = state.get("data", 0)
        bit_index = state.get("bit_index", 0)

        if phase == 0:
            tx = 1
            if inputs.get("in_valid", 0):
                phase = 1
                tx = 0
                count = div - 1
                data = int(inputs.get("in_data", 0)) & 255
                bit_index = 0
        elif count > 0:
            count = count - 1
        elif phase == 1:
            phase = 2
            tx = (data >> bit_index) & 1
            count = div - 1
        elif phase == 2:
            if bit_index < 7:
                bit_index = bit_index + 1
                tx = (data >> bit_index) & 1
                count = div - 1
            else:
                phase = 3
                tx = 1
                count = div - 1
        else:
            phase = 0
            tx = 1
            count = 0

        state = dict(phase=phase, tx=tx, count=count, data=data, bit_index=bit_index)

    outputs = dict(tx=state.get("tx", 1) & 1)
    return state, outputs
